/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/popover.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
"use client";

import * as React from "react";
import { Popover as PopoverPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
function Popover({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Root> & CapconsBasePropsLoose) {
  return <PopoverPrimitive.Root data-slot="popover" {...capconsSpread(props)} />;
}
function PopoverTrigger({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Trigger> & CapconsBasePropsLoose) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...capconsSpread(props)} />;
}
function PopoverContent({
  className,
  align = "center",
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content> & CapconsBasePropsLoose) {
  return <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content data-slot="popover-content" align={align} sideOffset={sideOffset} className={cn("z-50 w-72 origin-(--radix-popover-content-transform-origin) rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95", className)} {...capconsSpread(props)} />
    </PopoverPrimitive.Portal>;
}
function PopoverAnchor({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Anchor> & CapconsBasePropsLoose) {
  return <PopoverPrimitive.Anchor data-slot="popover-anchor" {...capconsSpread(props)} />;
}
function PopoverHeader({
  className,
  ...props
}: React.ComponentProps<"div"> & CapconsBasePropsLoose) {
  return <div data-slot="popover-header" className={cn("flex flex-col gap-1 text-sm", className)} {...capconsSpread(props)} />;
}
function PopoverTitle({
  className,
  ...props
}: React.ComponentProps<"h2"> & CapconsBasePropsLoose) {
  return <div data-slot="popover-title" className={cn("font-medium", className)} {...capconsSpread(props)} />;
}
function PopoverDescription({
  className,
  ...props
}: React.ComponentProps<"p"> & CapconsBasePropsLoose) {
  return <p data-slot="popover-description" className={cn("text-muted-foreground", className)} {...capconsSpread(props)} />;
}
export { Popover, PopoverTrigger, PopoverContent, PopoverAnchor, PopoverHeader, PopoverTitle, PopoverDescription };
